package dev.gbppimentel.zzz;
import org.json.*;import java.util.*;
/** Roster-wide public portraits, registered separately for active and reserve HUD slots. */
final class PortraitMatcher {
 static final class Ref{String id,kind,role;double[] vector;}
 final List<Ref> refs=new ArrayList<>();
 PortraitMatcher(String json)throws Exception{JSONArray a=new JSONArray(json);for(int i=0;i<a.length();i++){JSONObject j=a.getJSONObject(i);Ref r=new Ref();r.id=j.getString("id");r.kind=j.getString("kind");r.role=j.optString("role");JSONArray rgb=j.getJSONArray("rgb");if(rgb.length()!=864||r.role.isEmpty())throw new IllegalArgumentException("Outdated portrait model");double[] raw=new double[864];for(int k=0;k<raw.length;k++)raw[k]=rgb.getDouble(k);r.vector=interior(raw);normalize(r.vector);refs.add(r);}}
 static void normalize(double[] v){double mean=0,n=0;for(double x:v)mean+=x;mean/=v.length;for(int i=0;i<v.length;i++){v[i]-=mean;n+=v[i]*v[i];}n=Math.sqrt(n);for(int i=0;i<v.length;i++)v[i]/=Math.max(n,1);}
 // Ignore the slanted plate edges and the top/bottom health-bar overlap.
 static double[] interior(double[] raw){double[] v=new double[18*10*3];int k=0;for(int y=1;y<11;y++)for(int x=3;x<21;x++)for(int c=0;c<3;c++)v[k++]=raw[(y*24+x)*3+c];return v;}
 static double[] sample(int[] pixels,int width,int height,double x,double y,double w,double h){double[] raw=new double[864];int k=0;for(int yy=0;yy<12;yy++)for(int xx=0;xx<24;xx++){double red=0,green=0,blue=0;int count=0;int left=Math.max(0,(int)(x+xx*w/24)),right=Math.min(width,(int)(x+(xx+1)*w/24)),top=Math.max(0,(int)(y+yy*h/12)),bottom=Math.min(height,(int)(y+(yy+1)*h/12));for(int py=top;py<Math.max(top+1,bottom)&&py<height;py++)for(int px=left;px<Math.max(left+1,right)&&px<width;px++){int p=pixels[py*width+px];red+=(p>>16)&255;green+=(p>>8)&255;blue+=p&255;count++;}raw[k++]=red/Math.max(1,count);raw[k++]=green/Math.max(1,count);raw[k++]=blue/Math.max(1,count);}double[] v=interior(raw);normalize(v);return v;}
 JSONArray find(int[] pixels,int width,int height,String kind)throws Exception{JSONArray out=new JSONArray();if(!kind.equals("combat"))return out;Set<String> used=new HashSet<>();double[][] boxes={{64,26,62,22},{290,24,38,16},{382,24,36,16}};for(int slot=0;slot<boxes.length;slot++){double[] b=boxes[slot];String role=slot==0?"active":"reserve";Map<String,Double> scores=new HashMap<>();for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){double[] value=sample(pixels,width,height,(b[0]+dx)*width/960,(b[1]+dy)*height/540,b[2]*width/960,b[3]*height/540);for(Ref ref:refs){if(!ref.kind.equals(kind)||!ref.role.equals(role))continue;double score=0;for(int k=0;k<value.length;k++)score+=value[k]*ref.vector[k];scores.put(ref.id,Math.max(scores.getOrDefault(ref.id,0.0),score));}}
 String best="";double first=0,second=0;for(Map.Entry<String,Double> e:scores.entrySet())if(e.getValue()>first){second=first;first=e.getValue();best=e.getKey();}else second=Math.max(second,e.getValue());if(first>(slot==0?.85:.81)&&first-second>(slot==0?.065:.055)&&!used.contains(best)){out.put(new JSONObject().put("id",best).put("confidence",Math.round(first*100)/100.0).put("slot",slot));used.add(best);}}return out;}
}
